-- Theo dõi thứ hạng, traffic, backlink từng site; cảnh báo tụt đột ngột, tự chẩn đoán và mở phương án
CREATE TABLE IF NOT EXISTS mon_state (site_id INTEGER PRIMARY KEY REFERENCES sites(id) ON DELETE CASCADE, settings TEXT NOT NULL DEFAULT '{}', state TEXT NOT NULL DEFAULT '{}', updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS mon_daily (site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, day TEXT NOT NULL, clicks REAL NOT NULL DEFAULT 0, impressions REAL NOT NULL DEFAULT 0, position REAL, PRIMARY KEY (site_id, day));
CREATE TABLE IF NOT EXISTS mon_pages (site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, page TEXT NOT NULL, clicks7 REAL NOT NULL DEFAULT 0, clicks_prev REAL NOT NULL DEFAULT 0, impr7 REAL NOT NULL DEFAULT 0, impr_prev REAL NOT NULL DEFAULT 0, pos7 REAL, pos_prev REAL, updated_at INTEGER NOT NULL, PRIMARY KEY (site_id, page));
CREATE TABLE IF NOT EXISTS mon_queries (site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, query TEXT NOT NULL, page TEXT NOT NULL, clicks7 REAL NOT NULL DEFAULT 0, clicks_prev REAL NOT NULL DEFAULT 0, impr7 REAL NOT NULL DEFAULT 0, pos7 REAL, pos_prev REAL, updated_at INTEGER NOT NULL, PRIMARY KEY (site_id, query, page));
CREATE TABLE IF NOT EXISTS mon_keywords (id INTEGER PRIMARY KEY AUTOINCREMENT, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, keyword TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'auto', pos INTEGER, url TEXT, prev_pos INTEGER, best_pos INTEGER, features TEXT, checked_at INTEGER, active INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, UNIQUE (site_id, keyword));
CREATE TABLE IF NOT EXISTS mon_rank_history (keyword_id INTEGER NOT NULL REFERENCES mon_keywords(id) ON DELETE CASCADE, day TEXT NOT NULL, pos INTEGER, url TEXT, PRIMARY KEY (keyword_id, day));
CREATE TABLE IF NOT EXISTS mon_backlinks (site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, day TEXT NOT NULL, backlinks INTEGER, domains INTEGER, rank INTEGER, broken INTEGER, PRIMARY KEY (site_id, day));
CREATE TABLE IF NOT EXISTS mon_bl_changes (id INTEGER PRIMARY KEY AUTOINCREMENT, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, kind TEXT NOT NULL, source_url TEXT NOT NULL, domain TEXT, target_url TEXT NOT NULL DEFAULT '', anchor TEXT, dofollow INTEGER, at_date TEXT, seen_at INTEGER NOT NULL, UNIQUE (site_id, kind, source_url, target_url));
CREATE TABLE IF NOT EXISTS mon_alerts (id INTEGER PRIMARY KEY AUTOINCREMENT, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, kind TEXT NOT NULL, severity TEXT NOT NULL, title TEXT NOT NULL, detail TEXT, plan TEXT, status TEXT NOT NULL DEFAULT 'open', recheck_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_mon_alerts ON mon_alerts(site_id, status);
CREATE TABLE IF NOT EXISTS google_updates (name TEXT PRIMARY KEY, kind TEXT NOT NULL, started TEXT NOT NULL, ended TEXT, note TEXT, updated_at INTEGER NOT NULL);
